import React from "react";
import PropTypes from "prop-types";
import { compose } from "redux";
import {
  commonRulesMapDisToProps,
  commonRulesReducers,
  commonRulesSelector,
  fetchData,
  fetchRuleSet,
} from "./CommonRuleRedux";
import { connect } from "react-redux";
import { required } from "./ValidationUtil";
import { toTitleCase, download } from "./CommonRuleFunctions";
import applyReducers from "@traveloka/soya-components/lib/legacy/applyReducers";
import { Button } from "@traveloka/soya-components";
import CommonRuleComponent from "./CommonRuleComponent";
import CommonRuleModal from "./CommonRuleModal";
import CommonRuleService from "./CommonRuleService";
import FloatButton from "./FloatButton/FloatButton";
import ImportFileModal from "./ImportFileModal";
import {
  NotificationManager,
  ModalManager,
  Icon,
  Label,
  Loader,
  Row,
  Select,
  Tooltip,
  TETHER_ATTACHMENTS,
  Text,
  DropDownItem,
  DropDownMenu,
  DropDownToggle,
  DropDown,
  Divider,
  Column,
} from "@traveloka/soya-components";
import TextInput from "./TextInput";

import * as style from "./CommonRule.styles";

class CommonRuleContainer extends React.Component {
  constructor(props) {
    super(props);
    const Service = props.CustomRuleService || CommonRuleService;
    this.state = {
      show: true,
      releaseNotes: "",
      versions: [],
      currentVersion: -1,
      loading: true,
    };
    this.service = new Service();
  }

  loadData(props) {
    fetchData(this.service, props, this.state.currentVersion).then(() => {
      this.setState({ loading: false });
    });
  }

  loadVersions(props) {
    this.service
      .getAllVersions({ ruleSetHeader: props.ruleSetHeader })
      .then(({ data }) => {
        if (data.data.versions.length !== 0) {
          this.setState({
            versions: this.convertVersionFromStrToInt(data.data.versions),
          });
        }
      });
  }

  convertVersionFromStrToInt(versions) {
    const result = [];
    for (const version in versions) {
      const convertedVersion = versions[version];
      convertedVersion.version = parseInt(convertedVersion.version, 10);
      result.push(convertedVersion);
    }
    return result;
  }

  componentDidMount() {
    this.loadData(this.props);
    this.loadVersions(this.props);
  }

  handleSave = () => {
    ModalManager.show({
      title: `Input release note`,
      body: (
        <div>
          <Label>Release Notes</Label>
          <TextInput
            placeholder={"release notes here"}
            name="releaseNotes"
            onChange={this.handleInputChange}
            validators={[required]}
            isTextArea
          />
        </div>
      ),
      footer: (
        <div>
          <Button variant="link" onClick={() => ModalManager.dismiss()}>
            Cancel
          </Button>
          <Button variant="blue" onClick={() => this.handleSaveRule()}>
            Done!
          </Button>
        </div>
      ),
    });
  };

  handleSaveRule = () => {
    const { releaseNotes } = this.state;
    const { ruleSetHeader, rules } = this.props;
    if (releaseNotes) {
      this.service
        .saveRuleSet({ ruleSetHeader, releaseNotes, rules })
        .then(({ data }) => {
          if (data && data.data.status === "SUCCESS") {
            NotificationManager.showSuccess(
              "Your changes has been successfully saved"
            );
            this.loadVersions(this.props);
            this.setState({
              currentVersion: parseInt(data.data.ruleSetId.version, 10),
            });
          } else {
            const message = data && data.data.message ? data.data.message : "";
            NotificationManager.showError("Error in saving data: " + message);
          }
        });
      ModalManager.dismiss();
    } else {
      NotificationManager.showError("Release notes must be filled!");
    }
  };

  handleInputChange = (name, value) => {
    const stateObj = {};
    stateObj[name] = value;
    this.setState(stateObj);
  };

  handleShowNewRuleModal = () => {
    ModalManager.show({
      title: `Add New Rule`,
      body: (
        <CommonRuleModal
          onCancel={this.handleCancelModalManager}
          onSave={this.handleAddNewRule}
          mode="create"
        />
      ),
      footer: " ",
    });
  };

  handleAddNewRule = (newRule) => {
    const { addRule } = this.props;
    newRule.conditions = [];
    newRule.actions = [];
    addRule(newRule);
    ModalManager.dismiss();
  };

  handleCancelModalManager = () => {
    ModalManager.dismiss();
  };

  handleVersionChange = (value) => {
    if (this.state.currentVersion !== value) {
      fetchRuleSet(this.service, this.props, value);
      this.setState({ currentVersion: value });
    }
  };

  handleExportRuleSet = () => {
    this.service
      .exportRuleSet({
        ruleSetHeader: this.props.ruleSetHeader,
        version: this.state.currentVersion,
      })
      .then(({ data }) => {
        if (data.data && data.data.exportedData) {
          const bytes = data.data.exportedData.bytes;
          const fileName =
            data.data.exportedData.fileName +
            "." +
            data.data.exportedData.fileType.toLowerCase();
          download(fileName, bytes);
        }
      });
  };

  handleImportRuleSet = () => {
    ModalManager.show({
      title: `Import Rule Set`,
      body: (
        <ImportFileModal
          onSave={this.handleSubmitImport}
          onCancel={this.handleCancelModalManager}
        />
      ),
      footer: " ",
    });
  };

  handleSubmitImport = (file, releaseNotes) => {
    this.service
      .importRuleSet(
        { ruleSetHeader: this.props.ruleSetHeader, releaseNotes },
        file
      )
      .then(({ data }) => {
        if (data && data.data.status === "SUCCESS") {
          NotificationManager.showSuccess(
            "Rules has been successfully imported"
          );
          this.loadVersions(this.props);
          this.setState({
            currentVersion: parseInt(data.data.ruleSetId.version, 10),
          });
          fetchRuleSet(this.service, this.props, data.data.ruleSetId.version);
        } else {
          const message = data && data.data.message ? data.data.message : "";
          NotificationManager.showError("Error in importing rules: " + message);
        }
      });
    ModalManager.dismiss();
  };

  collapseAll = () => {
    this.setState({ show: false });
  };

  showAll = () => {
    this.setState({ show: true });
  };

  toTop = () => {
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  toBottom = () => {
    this.containerEnd.scrollIntoView({ behavior: "smooth" });
  };

  renderCommonRuleComponent = () => {
    const { ruleLength } = this.props;
    const ruleComponents = [];
    for (let i = 0; i < ruleLength; i++) {
      ruleComponents.push(
        <CommonRuleComponent
          key={i}
          index={i}
          lastIndex={ruleLength}
          show={this.state.show}
          isDragging={false}
        />
      );
    }
    return ruleComponents;
  };

  render() {
    const { ruleLength, ruleSetHeader } = this.props;
    const { currentVersion, loading, versions } = this.state;
    const items = [];
    let versionInfo = "";

    let latestVersion = versions.length > 0 ? -1 : "";
    for (const i in versions) {
      if (latestVersion < versions[i].version) {
        latestVersion = versions[i].version;
      }

      if (
        (currentVersion === -1 && versions[i].version === latestVersion) ||
        (currentVersion !== -1 && currentVersion === versions[i].version)
      ) {
        versionInfo = (
          <div>
            <div>Created By: {versions[i].createdBy}</div>
            <div>Created At: {versions[i].createdAt}</div>
            <div>Release Notes: {versions[i].releaseNote}</div>
          </div>
        );
      }

      items.push({
        label: "Version: " + versions[i].version,
        value: versions[i].version,
      });
    }

    const defaultVersion =
      currentVersion === -1 ? latestVersion : currentVersion;

    if (loading) return <Loader />;
    // const ruleComponents = [];
    // for (let i = 0; i < ruleLength; i++) {
    //   ruleComponents.push(
    //     <CommonRuleComponent key={i} index={i} lastIndex={ruleLength} show={this.state.show} isDragging={false} />
    //   );
    // }
    // console.log(ruleComponents);

    const children = [
      {
        text: "Collapse All",
        icon: "fullscreen-exit",
        handleClick: this.collapseAll,
      },
      {
        text: "Show All",
        icon: "zoom-out-map",
        handleClick: this.showAll,
      },
      {
        text: "To Top",
        icon: "chevron-double-up",
        handleClick: this.toTop,
      },
      {
        text: "To Bottom",
        icon: "chevron-double-down",
        handleClick: this.toBottom,
      },
    ];

    return (
      <div>
        <Row marginBottom>
          <Column size={12}>
            <Text tag="h1">
              {toTitleCase(ruleSetHeader)}
              <div className="topbar button" style={{ float: "right" }}>
                <DropDown size="md">
                  <DropDownToggle>Available Actions</DropDownToggle>
                  <DropDownMenu isRight>
                    <DropDownItem
                      className={style.dropdownItem}
                      onClick={this.handleSave}
                    >
                      Save Ruleset
                    </DropDownItem>
                    <DropDownItem
                      className={style.dropdownItem}
                      onClick={this.handleShowNewRuleModal}
                    >
                      Add New Rule
                    </DropDownItem>
                    <DropDownItem
                      className={style.dropdownItem}
                      onClick={this.handleImportRuleSet}
                    >
                      Import Ruleset
                    </DropDownItem>
                    <DropDownItem
                      className={style.dropdownItem}
                      onClick={this.handleExportRuleSet}
                    >
                      Export Ruleset
                    </DropDownItem>
                  </DropDownMenu>
                </DropDown>
              </div>
            </Text>
            <Divider />
            <Label>Selected Version</Label>
            <div className="versioning" style={{ display: "flex" }}>
              <Select
                options={items}
                defaultValue={defaultVersion}
                onChange={this.handleVersionChange}
                width="15%"
              />
              <Icon
                id="version-details"
                icon="info-circle-outline"
                style={{ marginTop: "5px", marginLeft: "5px" }}
              />
              <Tooltip
                placement={TETHER_ATTACHMENTS.RIGHT}
                target="#version-details"
                trigger="hover"
              >
                {versionInfo}
              </Tooltip>
            </div>
            <Divider />
          </Column>
        </Row>
        {/* {ruleComponents.map((item, index) => item)} */}
        {this.renderCommonRuleComponent()}
        <FloatButton actions={children} />
        <div
          style={{ float: "left", clear: "both" }}
          ref={(el) => {
            this.containerEnd = el;
          }}
        />
      </div>
    );
  }
}

CommonRuleContainer.propTypes = {
  ruleSetHeader: PropTypes.string.isRequired,
  ruleLength: PropTypes.number,
  CustomRuleService: PropTypes.func,
};

const mapStateToProps = (state) => ({
  ruleLength: commonRulesSelector.getRulesLength(state),
  rules: commonRulesSelector.getRules(state),
});

export default compose(
  applyReducers(commonRulesReducers),
  connect(mapStateToProps, commonRulesMapDisToProps)
)(CommonRuleContainer);
